/* legacy.h — la incluye al final msp430fr2311.h (la cabecera de TI que hay en
 * doc/refs); no viene en el paquete. Esa cabecera se declara
 * __AUTOGENERATED__, y entonces la DriverLib (inc/hw_memmap.h) no incluye
 * msp430fr2xx_4xxgeneric.h; de allí solo falta esto, los desplazamientos
 * genéricos de la eUSCI_A que usa eusci_a_uart.c (los mismos valores que en
 * msp430fr2xx_4xxgeneric.h). Los nombres antiguos de legacy.h no se usan. */
#define OFS_UCAxCTLW0 (0x0000)
#define OFS_UCAxCTLW1 (0x0002)
#define OFS_UCAxBRW   (0x0006)
#define OFS_UCAxMCTLW (0x0008)
#define OFS_UCAxSTATW (0x000A)
#define OFS_UCAxRXBUF (0x000C)
#define OFS_UCAxTXBUF (0x000E)
#define OFS_UCAxIE    (0x001A)
#define OFS_UCAxIFG   (0x001C)
/* Y el PMM: esta cabecera lo llama __MSP430_HAS_PMM__; la DriverLib (pmm.h,
 * pmm.c) pregunta por __MSP430_HAS_PMM_FRAM__ */
#ifndef __MSP430_HAS_PMM_FRAM__
#define __MSP430_HAS_PMM_FRAM__
#endif
